package publish

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/binds/cli.go, and what it
// returns is one entry of sandbox.Commands.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) *api.Command {
	command := api.NewCommand()

	command.Name = "publish"
	command.Identifiers = []string{"publish"}
	command.Category = "Core Commands"
	command.Help = "Builds, compiles and publishes a release via gh"
	command.LongDescription = "Runs build, then compile (every target by default), and publishes every file of release/ as a gh release named --release-name, defaulting to the version in AgnosConfig/project.yaml."
	command.Examples = []string{}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "The directory holding the project (defaults to the current directory)",
			Examples:    []string{},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path", "-p"},
		},
		{
			Id:          "release_name",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "The name of the release",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--release-name", "-rn"},
		},
		{
			Id:          "draft",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Create a draft release",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--draft"},
		},
		{
			Id:          "target",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "The target to compile for (defaults to all)",
			Examples:    []string{},
			Default:     "all",
			HasDefault:  true,
			Identifiers: []string{"--target", "-t"},
		},
		{
			Id:          "publisher",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "The publisher to use (defaults to gh)",
			Examples:    []string{},
			Default:     "gh",
			HasDefault:  true,
			Identifiers: []string{"--publisher", "-pub"},
		},
	}

	command.Args = []api.CommandArg{}

	command.Handler = func() int {
		return CommandHandler(sandbox, command)
	}

	return command
}
